# region: emit
def emit(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: sift
def sift(xs, limit=12):
    return [v if v <= limit else limit for v in xs[1:]]

# region: intake
def intake(xs):
    return [v * v for v in xs]

# region: render
def render(xs, offset=-1):
    return [v + offset for v in xs]

# region: digest
def digest(xs, cut=8):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: gather
def gather(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return gather(digest(render(intake(sift(emit(raw))))))

